'use strict';

const UNIT_MS = { ms: 1, s: 1000, m: 60000, h: 3600000, d: 86400000 };

function parseDuration(str) {
  if (typeof str !== 'string') throw new TypeError('Duration must be a string');
  const text = str.trim();
  if (!/^(?:\d+(?:\.\d+)?(?:ms|[smhd]))+$/.test(text)) {
    throw new TypeError('Invalid duration');
  }

  const parts = text.matchAll(/(\d+(?:\.\d+)?)(ms|[smhd])/g);
  for (const [, amount, unit] of parts) {
    const milliseconds = Number(amount) * UNIT_MS[unit];
    if (!Number.isFinite(milliseconds)) throw new TypeError('Duration overflow');
    return milliseconds;
  }
}

module.exports = { parseDuration };
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { parseDuration } = require('../src/duration');

test('single-unit durations and decimals', () => {
  assert.equal(parseDuration('45s'), 45000);
  assert.equal(parseDuration('1.5h'), 5400000);
  assert.equal(parseDuration('250ms'), 250);
});

test('compound duration includes all parts', () => {
  assert.equal(parseDuration('1h30m'), 5400000);
});

test('invalid values are not silently accepted', () => {
  for (const value of ['', '10', '2weeks', '3s garbage', 42]) {
    assert.throws(() => parseDuration(value), TypeError);
  }
});


